    if _MODULE is None:
        _MODULE = PtxModule(PTX_SOURCE)
    return _MODULE


def validate_generated_code():
    """Look up the compiled kernel entry to validate the PTX module."""
    module = _get_module()
    return module.function("gelu_kernel")


class ModelNew(nn.Module):
    """
    GELU (tanh approximation) implemented with a hand-authored PTX kernel
    executed through cutegen.ptx_runtime.PtxModule.
    """

    def __init__(self) -> None:
        super().__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "x must be a CUDA tensor"
        assert x.dtype == torch.float32, "x must be float32"

        x_c = x.contiguous()
        y = torch.empty_like(x_c)

        N = x_c.numel()

        threads = 256
        Nvec = N // 4
        blocks_needed = (Nvec + threads - 1) // threads
        if blocks_needed < 1:
            blocks_needed = 1

        # ------------------------------------------------------------------
        # Occupancy-aware grid sizing.
        #
        # The kernel already implements a grid-stride loop over the vector
        # chunks, so it is unnecessary (and, per profiling, harmful) to
        # launch one block per chunk. With `threads=256` and the measured
        # register usage (~40 regs/thread), each SM on this architecture
        # can concurrently host at most 6 resident blocks (thread-count
        # limited: 1536 max resident threads/SM / 256 threads-per-block).
        # Launching far more blocks than can be resident at once (as the
        # naive `blocks_needed` sizing does) causes the grid to execute in
        # many sequential waves, and the final, partially-filled wave
        # under-utilizes the SMs — this matches the profiled gap between
        # theoretical (100%) and achieved (~80.7%) occupancy.
        #
        # Instead, size the grid to (SM count * blocks-per-SM) so that a
        # single wave saturates the device, and let each thread iterate
        # over multiple chunks via the existing stride loop. This removes
        # the tail-wave inefficiency without altering kernel semantics.
        # ------------------------------------------------------------------
        try:
            sm_count = torch.cuda.get_device_properties(x_c.device).multi_processor_count
        except Exception:
            sm_count = 128  # fall back to RTX 4090's SM count

        blocks_per_sm = 6  # thread-limited occupancy for 256 threads/block on sm_89
        occupancy_blocks = sm_count * blocks_per_sm

        blocks = min(blocks_needed, occupancy_blocks)
        if blocks < 1:
            blocks = 1

        module = _get_module()
        stream = torch.cuda.current_stream()

        module.launch(
            "gelu_kernel",
            (blocks, 1, 1),
            (threads, 1, 1),
            (u64(x_c.data_ptr()), u64(y.data_ptr()), i64(N)),
            stream=stream,
        )

        return y

