cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <math.h>
#include <cute/tensor.hpp>

using namespace cute;

__global__ void gelu_kernel(const float* __restrict__ X,
                             float* __restrict__ Y,
                             int64_t N)
{
  constexpr int Vec = 4;
  const int64_t tid    = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
  const int64_t stride = (int64_t)blockDim.x * gridDim.x;

  const int64_t Nvec     = N / Vec;
  const int64_t rem_start = Nvec * Vec;

  const float c = 0.7978845608028654f; // sqrt(2/pi)

  // Vectorized path using CuTe tensors over float4 view
  auto mX = make_tensor(make_gmem_ptr(reinterpret_cast<const float4*>(X)),
                         make_shape(Nvec));
  auto mY = make_tensor(make_gmem_ptr(reinterpret_cast<float4*>(Y)),
                         make_shape(Nvec));

  for (int64_t i = tid; i < Nvec; i += stride) {
    float4 v = mX(i);
    float4 r;

    float x0 = v.x;
    float x1 = v.y;
    float x2 = v.z;
    float x3 = v.w;

    float t0 = tanhf(c * (x0 + 0.044715f * x0 * x0 * x0));
    float t1 = tanhf(c * (x1 + 0.044715f * x1 * x1 * x1));
    float t2 = tanhf(c * (x2 + 0.044715f * x2 * x2 * x2));
    float t3 = tanhf(c * (x3 + 0.044715f * x3 * x3 * x3));

    r.x = 0.5f * x0 * (1.0f + t0);
    r.y = 0.5f * x1 * (1.0f + t1);
    r.z = 0.5f * x2 * (1.0f + t2);
    r.w = 0.5f * x3 * (1.0f + t3);

    mY(i) = r;
  }

  // Remainder (in case N is not divisible by 4)
  for (int64_t i = rem_start + tid; i < N; i += stride) {
    float x = X[i];
    float t = tanhf(c * (x + 0.044715f * x * x * x));
    Y[i] = 0.5f * x * (1.0f + t);
  }
}

