  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");

  auto x_c = x.contiguous();
  auto y = torch::empty_like(x_c);

  int64_t N = x_c.numel();

  const int threads = 256;
  int64_t Nvec = N / 4;
  int64_t blocks_needed = (Nvec + threads - 1) / threads;
  if (blocks_needed < 1) blocks_needed = 1;
  int blocks = (int)std::min<int64_t>(blocks_needed, 65535 * 32);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  gelu_kernel<<<blocks, threads, 0, stream>>>(
      x_c.data_ptr<float>(),
      y.data_ptr<float>(),
      N
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "gelu_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
